def main():
    sources = json.loads(Path("source.json").read_text())
    Path("drafts/150-0-A.xml").write_text("".join(
        Path(f"drafts/150-0-A-part{i}.xml").read_text() for i in range(1, 4)
    ))
    result = []
    for source in sources:
        number = source["number"]
        reason, review_notes = DETAILS[number]
        result.append({
            **{key: source[key] for key in (
                "code_id", "source_id", "source_sha256", "number"
            )},
            "proposed_xml": Path(f"drafts/{number.replace(' ', '-')}.xml").read_text().strip(),
            "reason": reason,
            "review_notes": review_notes,
            "status": "rewrite_draft",
        })
    Path("answer.json").write_text(json.dumps(result, ensure_ascii=False, indent=2) + "\n")


if __name__ == "__main__":
    main()
